discrete MechanicalSystem
port:
    event input real WindSpeed;  // Wind speed input
event output real MaintenanceSignal;  // Maintain signal output
state:
    initial state StandbyState
        when entry() then
            statehold(0);
        end;
        when receive(WindSpeed) then
            transition(RunState);
        end;
    end;

    state RunState
        when entry() then
            statehold(0);
        end;
        when detect(AbnormalCondition) then
            transition(FaultState);
        end;
        when timeover() then
            transition(MaintenanceState);
        end;
    end;

    state FaultState
        when entry() then
            statehold(0);
        end;
        when receive(RepairCompleted) then
            transition(StandbyState);
        end;
        when detect(NeedMaintenance) then
            transition(MaintenanceState);
        end;
    end;

    state MaintenanceState
        when entry() then
            statehold(0);
        end;
        when receive(MaintenanceCompleted) then
            transition(StandbyState);
        end;
    end;
end;
end;

discrete ControlSystem
port:
    event input real ExternalCondition;  // External condition input
event output real EmergencyStopSignal;  // Emergency shutdown signal output.
state:
    initial state MonitoringMode
        when entry() then
            statehold(0);
        end;
        when receive(ExternalCondition) then
            transition(RegulationMode);
        end;
    end;

    state RegulationMode
        when entry() then
            statehold(0);
        end;
        when receive(ExternalCondition) then
            transition(MonitoringMode);
        end;
    end;

    state EmergencyStopMode
        when entry() then
            statehold(0);
        end;
        when receive(ExternalCondition) then
            transition(MonitoringMode);
        end;
    end;
end;
end;

discrete PowerConversionSystem
port:
    event input real InputCurrent;
    event output real OverloadProtectionSignal;
state:
    initial state NormalOperationState
        when entry() then
            statehold(0);
        end;
        when receive(InputCurrent) then
            transition(OverloadProtectionState);
        end;
    end;

    state OverloadProtectionState
        when entry() then
            statehold(0);
        end;
        when receive(InputCurrent) then
            transition(NormalOperationState);
            out
                send(OverloadProtectionSignal, 1);
        end;
    end;

    state CoolingState
        when entry() then
            statehold(0);
        end;
        when receive(InputCurrent) then
            transition(NormalOperationState);
        end;
    end;
end;
end;

couple WindTurbineSystem
import architectureModels.MechanicalSystem as MS;
import architectureModels.ControlSystem as CS;
import architectureModels.PowerConversionSystem as PCS;

part:
    MS MechanicalInstance;
    CS ControlInstance;
