connection:
    connect(MechanicalInstance.WindSpeedInput, ControlInstance.WindSpeedOutput);
    connect(ControlInstance.EmergencyStopOutput, PowerInstance.EmergencyStopInput);
    connect(PowerInstance.OverloadOutput, MechanicalInstance.MaintenanceInput);
end;
